/**
 * 일괄로직점검 팝업창 
 */
/**
 * @method
 * @name fn_OpenLogicCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenLogicCheck = async function() {
    await $c.frame.CreateDialogFrame("LOSSLMT_ETNLOGIGCHK", "/etn/ULDSTF08131.gfm", "ETN 일괄로직점검(손실제한)", 200, 100, 770, 450, "window");
};



/********************************************** 
 * 함수명 : fn_CheckForm(procTyp)
 * 설명    : 반송구분/반송사유 체크
 **********************************************/
/**
 * @method
 * @name fn_CheckForm
 * @description desc
 * @param {string} procTyp desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckForm = function(procTyp) {
    if (procTyp == "2") {
        if (cmb_RETN_BZ_TP_CD.getValue() == "") {
            alert("[반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if (txb_RET_RSN.getValue() == "") {
            alert("[반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    } else {
        if (cmb_RETN_BZ_TP_CD.getValue() != "") {
            alert("반송시에만 [반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if (txb_RET_RSN.getValue() != "") {
            alert("반송시에만 [반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명 : fn_recv_acpt()
 * 설명   : ETN 접수처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_acpt
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_acpt = function() {
    if (scwin.fn_CheckForm("1")) {
        procJob = "접수처리";
        var res = window.confirm(procJob + "하시겠습니까?");
        if (res) {
            dts_Isu.setCellData(1, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_10);
            scwin.fn_recv_trs();
        }
    }
};




/********************************************** 
 * 함수명 : fn_recv_ret()
 * 설명   : ETN 반송처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_ret
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_ret = function() {
    if (scwin.fn_CheckForm("2")) {
        procJob = "반송";
        var res = window.confirm(procJob + "하시겠습니까?");
        if (res) {
            dts_Isu.setCellData(1, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_02);
            dts_Isu.setCellData(1, "RET_RSN_CD", cmb_RETN_BZ_TP_CD.getValue());
            dts_Isu.setCellData(1, "RET_RSN", cmb_RETN_BZ_TP_CD.getValue() + ":" + txb_RET_RSN.getValue());
            scwin.fn_recv_trs();
        }
    }
};




/********************************************** 
 * 함수명 : fn_recvret_trs()
 * 설명   : ETN 반송처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_trs
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_trs = function() {
    trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnListedRcv.do?method=receiveEtnAcptRet&SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명 : fn_RetRsn_Search()
 * 설명   : ETN 반송사유 조회
 **********************************************/
/**
 * @method
 * @name fn_RetRsn_Search
 * @description desc
 * @param {string} paramBzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RetRsn_Search = function(paramBzProcsNo) {
    var url = "/etn/EtnListedRcv.do";
    url += "?method=readRecvEtnRetRsn";
    url += "&SCREN_ID=" + vScrenID;
    url += "&outputMessageId=ETN_LISTEDRCV_RESRSN_SEARCH_OUT";
    url += "&SCREN_ID=" + fr_SecuGrpId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&BZ_PROCS_NO=" + paramBzProcsNo;
    dts_RetRsn.DataID = encodeURI(url);
    dts_RetRsn.Reset();
    txb_RET_RSN.setValue(dts_RetRsn.getCellData(1, "RET_RSN"));
};



/********************************************** 
 * 함수명 : fn_SetRetTypeCombo()
 * 설명   : ETN심사청구반송구분코드 조회
 **********************************************/
/**
 * @method
 * @name fn_SetRetTypeCombo
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetRetTypeCombo = function(dtsObj) {
    var url = "/CodeAction.do?method=listCodeValueName";
    url += "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT";
    url += "&SCREN_ID=" + fr_SecuGrpId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ENG_NM=ETN_INVSTG_CLM_RET_TP_CD";
    url += "&For=R";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


/**
 * 종목상세정보 팝업창
 */
/**
 * @method
 * @name fn_OpenDetailRecv
 * @description desc
 * @param {string} vbzTpCd desc
 * @param {string} vetpProdTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailRecv = async function(vbzTpCd, vetpProdTpCd) {
    var screenId = "";
    var screenNm = "";
    if (vetpProdTpCd == "4") {
        //	손실제한
        if (vbzTpCd == LIST_BZ_TP_CD_701) {
            screenId = "ULDSTF08102";
            screenNm = "ETN신규예비심사청구내역(손실제한)";
        } else if (vbzTpCd == LIST_BZ_TP_CD_702) {
            screenId = "ULDSTF08103";
            screenNm = "ETN신규상장신청내역(손실제한)";
        } else if (vbzTpCd == LIST_BZ_TP_CD_703) {
            screenId = "ULDSTF08104";
            screenNm = "ETN추가상장심사청구내역(손실제한)";
        } else if (vbzTpCd == LIST_BZ_TP_CD_704) {
            screenId = "ULDSTF08105";
            screenNm = "ETN추가상장신청내역(손실제한)";
        }
    } else {
        if (vbzTpCd == LIST_BZ_TP_CD_701) {
            screenId = "ULDSTF08002";
            screenNm = "ETN신규예비심사청구내역";
        } else if (vbzTpCd == LIST_BZ_TP_CD_702) {
            screenId = "ULDSTF08003";
            screenNm = "ETN신규상장신청내역";
        } else if (vbzTpCd == LIST_BZ_TP_CD_703) {
            screenId = "ULDSTF08004";
            screenNm = "ETN추가상장심사청구내역";
        } else if (vbzTpCd == LIST_BZ_TP_CD_704) {
            screenId = "ULDSTF08005";
            screenNm = "ETN추가상장신청내역";
        }
    }
    await $c.frame.CreateDialogFrame("DLG_ETNRECV", "/etn/" + screenId + ".gfm", screenNm, 10, -50, 1104, 920, "window");
};


