rptType_01 = '01'; //신규상장 심사청구
rptType_02 = '02'; //신규상장 상장신청
rptType_03 = '03'; //추가상장 심사청구
rptType_04 = '04'; //추가상장 상장신청

rptEtpPordTpCd_03 = '03'; // 일반
rptEtpPordTpCd_04 = '04'; // 손실제한


vEtnIsuQtyLabel = "";
vEtnIsuOrgnValLabel = "";
vEtnIsuOrgnVal = "";
rpt_Header = "";

/**
 * 신규심사/상장, 추가심사/상장 구분
 * @param rptType
 */
/**
 * @method
 * @name fn_getEtnIsuQty
 * @description desc
 * @param {string} rptType desc
 * @param {string} rptetpProdTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getEtnIsuQty = function(rptType, rptetpProdTpCd) {
    if (rptType == scwin.rptType_01) {
        if (rptetpProdTpCd == scwin.rptEtpPordTpCd_03) {
            scwin.rpt_Header = "상장지수증권 신규상장 예비심사청구서";
        } else {
            scwin.rpt_Header = "상장지수증권 신규상장 예비심사청구서(손실제한)";
        }
        scwin.vEtnIsuQtyLabel = "발행수량(예정)";
        scwin.vEtnIsuOrgnValLabel = "발행원본액(예정)";
        scwin.vEtnIsuOrgnVal = dts_Isu.getCellData(1, "ISU_ORGN_VAL");
    } else if (rptType == scwin.rptType_02) {
        if (rptetpProdTpCd == scwin.rptEtpPordTpCd_03) {
            scwin.rpt_Header = "상장지수증권 신규상장신청서";
        } else {
            scwin.rpt_Header = "상장지수증권 신규상장신청서(손실제한)";
        }
        scwin.vEtnIsuQtyLabel = "발행수량";
        scwin.vEtnIsuOrgnValLabel = "발행원본액";
        scwin.vEtnIsuOrgnVal = dts_Isu.getCellData(1, "ISU_ORGN_VAL");
    } else if (rptType == scwin.rptType_03) {
        if (rptetpProdTpCd == scwin.rptEtpPordTpCd_03) {
            scwin.rpt_Header = "상장지수증권 추가상장 예비심사청구서";
        } else {
            scwin.rpt_Header = "상장지수증권 추가상장 예비심사청구서(손실제한)";
        }
        scwin.vEtnIsuQtyLabel = "추가발행수량(예정)";
        scwin.vEtnIsuOrgnValLabel = "추가발행원본액(예정)";
        scwin.vEtnIsuOrgnVal = dts_Isu.getCellData(1, "ISU_ORGN_VAL");
    } else if (rptType == scwin.rptType_04) {
        if (rptetpProdTpCd == scwin.rptEtpPordTpCd_03) {
            scwin.rpt_Header = "상장지수증권 추가상장신청서";
        } else {
            scwin.rpt_Header = "상장지수증권 추가상장신청서(손실제한)";
        }
        scwin.vEtnIsuQtyLabel = "추가발행수량";
        scwin.vEtnIsuOrgnValLabel = "추가발행원본액";
        scwin.vEtnIsuOrgnVal = dts_Isu.getCellData(1, "ISU_ORGN_VAL");
    }
};





/** 
 * etn 제3자 유동성공급자 목록
 */
/**
 * @method
 * @name fn_3LpInstList
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_3LpInstList = function() {
    if (vLpMbrNo != " " && vLpMbrNo != "") {
        var url = "/etn/EtnNewList.do?SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readEtnLpGrdList&inputMessageId=ETN_ISU_LP_GRD_OUT&BZ_PROCS_NO=" + vBzProcsNo + "&ISUR_CD=" + vIsurCd;
        dts_LpGrd.DataID = encodeURI(url);
        dts_LpGrd.Reset();
    }
};




/**
 * 예비심사(신규,추가) 청구 인쇄
 */
/**
 * @method
 * @name fn_pre_report
 * @description desc
 * @param {string} rptType desc
 * @param {string} rptetpProdTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_pre_report = function(rptType, rptetpProdTpCd) {
    scwin.fn_getEtnIsuQty(rptType, rptetpProdTpCd);
    scwin.fn_3LpInstList();

    /* PDF 변환시 visible 영역 지정 s */
    var hid = "";
    var reportTyp = cmb_PRINT_CD.getValue();
    if (reportTyp == "1") {
        //발행증권
        /*
         * iRpt2,iRptPage2 : 2.발행인에 관한 사항(HIDDEN)
         * iRpt3,iRptPage3 : 3.보증인/제3자 유동성공급자에 관한 사항(HIDDEN)
         * iRpt4 : 3.보증인/제3자 유동성공급자에 관한 사항-2. 제3자 유동성 공급자(HIDDEN)
         * */
        hid = "iRpt2,iRptPage2,iRpt3,iRptPage3,iRpt4";
    } else if (reportTyp == "2") {
        //발행회사
        /*
         * iRpt1,iRptPage1 : 1.발행증권에 관한 사항(HIDDEN)
         * iRpt3,iRptPage3 : 3.보증인/제3자 유동성공급자에 관한 사항(HIDDEN)
         * iRpt4 : 3.보증인/제3자 유동성공급자에 관한 사항-2. 제3자 유동성 공급자(HIDDEN)
         * */
        hid = "iRpt1,iRptPage1,iRpt3,iRptPage3,iRpt4";
    } else if (reportTyp == "3") {
        /*
         * iRpt1,iRptPage1 : 1.발행증권에 관한 사항(HIDDEN)
         * iRpt2,iRptPage2 : 2.발행인에 관한 사항(HIDDEN)
         * iRpt4 : 3.보증인/제3자 유동성공급자에 관한 사항-2. 제3자 유동성 공급자(HIDDEN)
         * */

        hid = "iRpt1,iRptPage1,iRpt2,iRptPage2";
    }
    if (dts_LpGrd.getTotalRow() == 0) {
        if (hid == "" || hid.length == 0) {
            hid = "iRpt4";
        } else {
            hid = hid + ",iRpt4";
        }
    }
    /* PDF 변환시 visible 영역 지정 e */

    var userParam = [{
        uid: "hid",
        unm: hid
    }, {
        uid: "HEADER",
        unm: scwin.rpt_Header
    }, {
        uid: "REPORT_TYP",
        unm: cmb_PRINT_CD.getValue()
    }, {
        uid: "ISU_KOR_NM",
        unm: dts_Isu.getCellData(1, "ISU_KOR_NM")
    }, {
        uid: "ISU_KOR_ABBRV",
        unm: dts_Isu.getCellData(1, "ISU_KOR_ABBRV")
    }, {
        uid: "ISU_ENG_NM",
        unm: dts_Isu.getCellData(1, "ISU_ENG_NM")
    }, {
        uid: "ISU_ENG_ABBRV",
        unm: dts_Isu.getCellData(1, "ISU_ENG_ABBRV")
    }, {
        uid: "ISU_CD",
        unm: dts_Isu.getCellData(1, "ISU_CD")
    }, {
        uid: "ISU_SRT_CD",
        unm: dts_Isu.getCellData(1, "ISU_SRT_CD")
    }, {
        uid: "ETN_ISU_QTY_LABEL",
        unm: scwin.vEtnIsuQtyLabel
    }, {
        uid: "ETN_ISU_QTY",
        unm: $c.stf.FormatNumberEx(dts_Isu.getCellData(1, "ETN_ISU_QTY"))
    }, {
        uid: "ISU_ORGN_VAL_LABEL",
        unm: scwin.vEtnIsuOrgnValLabel
    }, {
        uid: "ISU_ORGN_VAL",
        unm: $c.stf.FormatNumberEx(scwin.vEtnIsuOrgnVal)
    }, {
        uid: "IDX_NM",
        unm: dts_Isu.getCellData(1, "IDX_NM")
    }, {
        uid: "IDX_ENG_NM",
        unm: dts_Isu.getCellData(1, "IDX_ENG_NM")
    }, {
        uid: "IDX_CALC_INST_NM",
        unm: dts_Isu.getCellData(1, "IDX_CALC_INST_NM")
    }, {
        uid: "ISU_AGNT_TP_NM",
        unm: $c.stf.fn_getComboTextValue(cmb_ISU_AGNT_TP_CD)
    }, {
        uid: "ETN_BZ_ADM_COM_TP_NM",
        unm: $c.stf.fn_getComboTextValue(cmb_ETN_BZ_ADM_COM_TP_CD)
    }, {
        uid: "EXP_DD",
        unm: $c.stf.FormatDateEx(dts_Isu.getCellData(1, "EXP_DD"))
    }, {
        uid: "TAX_TP_NM",
        unm: $c.stf.fn_getComboTextValue(cmb_TAX_TP_CD)
    }, {
        uid: "IDX_LVRG_INVRS_TP_NM",
        unm: dts_Isu.getCellData(1, "IDX_LVRG_INVRS_TP_NM")
    }, {
        uid: "PRC_MLTPLR",
        unm: dts_Isu.getCellData(1, "PRC_MLTPLR")
    }, {
        uid: "DISTR_TP_NM",
        unm: $c.stf.fn_getComboTextValue(cmb_DISTR_TP_CD)
    }, {
