        unm: dts_Isu.getCellData(1, "DISTR_PAY_BAS_DD_CONTN")
    }, {
        uid: "DISTR_PAY_DD_CONTN",
        unm: dts_Isu.getCellData(1, "DISTR_PAY_DD_CONTN")
    }, {
        uid: "LP_HD_QTY",
        unm: dts_Isu.getCellData(1, "LP_HD_QTY")
    }, {
        uid: "DECL_SPD",
        unm: dts_Isu.getCellData(1, "DECL_SPD")
    }, {
        uid: "LSTTRD_DD",
        unm: $c.stf.FormatDateEx(dts_Isu.getCellData(1, "LSTTRD_DD"))
    }, {
        uid: "EXP_REDMPT_PRC_DECSN_STRT_DD",
        unm: $c.stf.FormatDateEx(dts_Isu.getCellData(1, "EXP_REDMPT_PRC_DECSN_STRT_DD"))
    }, {
        uid: "EXP_REDMPT_PRC_DECSN_END_DD",
        unm: $c.stf.FormatDateEx(dts_Isu.getCellData(1, "EXP_REDMPT_PRC_DECSN_END_DD"))
    }, {
        uid: "EXP_REDMPT_AMT_PAY_DD",
        unm: $c.stf.FormatDateEx(dts_Isu.getCellData(1, "EXP_REDMPT_AMT_PAY_DD"))
    }, {
        uid: "LST_SETL_METHD_NM",
        unm: $c.stf.fn_getComboTextValue(cmb_LST_SETL_METHD_CD)
    }, {
        uid: "HALFWY_REDMPT_UNIT",
        unm: $c.stf.FormatNumberEx(dts_Isu.getCellData(1, "HALFWY_REDMPT_UNIT"))
    }, {
        uid: "HALFWY_REDMPT_APPL_CYCLE_CONTN",
        unm: dts_Isu.getCellData(1, "HALFWY_REDMPT_APPL_CYCLE_CONTN")
    }, {
        uid: "HALFWY_REDMPT_PRC_DECSN_CONTN",
